"""Load a JSON config file."""
import json


class ConfigError(Exception):
    """Raised when a config file exists but cannot be parsed."""


def load_config(path):
    """Return the parsed config dict from `path`.

    Raises FileNotFoundError if the file is absent and ConfigError if it exists
    but is not valid JSON. Any other error propagates untouched.
    """
    with open(path) as f:            # a missing file raises FileNotFoundError, as it should
        try:
            return json.load(f)
        except json.JSONDecodeError as exc:
            raise ConfigError(f"invalid JSON in {path}: {exc}") from exc

